const app=document.querySelector('#app');
const state={view:'landing',onboard:0,alert:0,scenario:'likely',playing:false,time:44,sidebar:false};
const icons={overview:'⌂',simulation:'≈',forecast:'◒',evacuation:'⌁',alerts:'!',saved:'◇',learn:'?',settings:'⚙'};
const nav=[['overview','Overview'],['simulation','Simulation'],['forecast','Forecast'],['evacuation','Evacuation'],['alerts','Alerts'],['saved','Saved Locations'],['learn','Learn']];
function logo(){return `<button class="logo nav-to" data-view="landing" aria-label="StormSight home"><i class="logo-mark"></i><span>StormSight</span></button>`}
function weather(){return `<div class="weather" aria-hidden="true"><i class="cloud c1"></i><i class="cloud c2"></i><i class="mist"></i><i class="rain"></i></div>`}
function publicHeader(){return `<header class="public-header">${logo()}<nav class="public-nav" aria-label="Public navigation"><button class="nav-link scroll" data-target="features">Product</button><button class="nav-link nav-to" data-view="onboarding">How it works</button><button class="nav-link" onclick="toast('Demo data sources: PAGASA, NOAH, ECMWF and GloFAS')">Data</button><button class="nav-link" onclick="toast('StormSight is a preparedness prototype for Philippine communities.')">About</button><button class="btn btn-outline nav-to" data-view="login">Log in</button><button class="btn btn-danger nav-to" data-view="signup">Get Started</button></nav></header>`}
function landing(){return window.SSLanding.html()}
function auth(type){let signup=type==='signup';return `<main class="auth dimensional-auth"><button class="back-link nav-to" data-view="landing">← Back to home</button><section class="auth-scene">${weather()}<div style="position:relative;z-index:4">${logo()}</div><div class="scene-copy"><div class="eyebrow">JOIN STORMSIGHT</div><h1>${signup?'Prepare before<br>the storm.':'Know the risk.<br>Prepare earlier.'}</h1><p>${signup?'Save locations, monitor flood risk,<br>and receive local warnings.':'Return to your saved locations,<br>forecast data, and flood simulations.'}</p></div><img class="auth-iso" src="stormsight-isometric-flood-home.png" alt="3D flooded home model"></section><section class="auth-panel"><form class="form" onsubmit="handleAuth(event,'${type}')"><div class="form-kicker">STORMSIGHT ACCESS</div><h2>${signup?'Create your account':'Welcome back'}</h2><p class="form-sub">${signup?'Start monitoring the places that matter.':'Continue to your local flood outlook.'}</p>${signup?field('Full name','text','Ana Santos','fullName','name'):''}${field('Email','email','ana@example.com','email','email')}${field('Password','password','••••••••','password',signup?'new-password':'current-password')}${signup?field('Confirm password','password','••••••••','confirmPassword','new-password'):''}<button class="btn btn-primary" type="submit">${signup?'Create account →':'Log in →'}</button><div class="form-links">${!signup?'<button type="button" class="btn-quiet" onclick="handlePasswordReset()">Forgot password?</button><button type="button" class="btn-quiet nav-to" data-view="overview">Continue as guest</button>':''}<button type="button" class="btn-quiet nav-to" data-view="${signup?'login':'signup'}">${signup?'Already have an account? Log in':'Create account'}</button></div></form></section></main>`}
function field(label,type,placeholder,name,autocomplete){return `<div class="field"><label>${label}<input required type="${type}" name="${name}" autocomplete="${autocomplete}" placeholder="${placeholder}"></label></div>`}
async function handleAuth(event,type){event.preventDefault();let backend=window.StormSightBackend;if(!backend?.configured){toast('Backend is not configured yet. Guest mode is still available.');return}let form=event.currentTarget,data=new FormData(form),button=form.querySelector('[type=submit]');if(type==='signup'&&data.get('password')!==data.get('confirmPassword')){toast('Passwords do not match.');return}button.disabled=true;try{if(type==='signup'){let result=await backend.signUp(data.get('email'),data.get('password'),data.get('fullName'));if(!result.session){toast('Check your email to confirm your account.');return}go('onboarding')}else{await backend.signIn(data.get('email'),data.get('password'));go('overview')}}catch(error){toast(error.message||'Authentication failed.')}finally{button.disabled=false}}
async function handlePasswordReset(){let email=document.querySelector('input[name=email]')?.value;if(!email){toast('Enter your email address first.');return}try{await window.StormSightBackend.resetPassword(email);toast('Password reset email sent.')}catch(error){toast(error.message||'Could not send reset email.')}}
async function handleSignOut(){try{await window.StormSightBackend.signOut();toast('Signed out.');go('landing')}catch(error){toast(error.message||'Could not sign out.')}}
const steps=[{title:'Start with the place that matters.',copy:'StormSight uses your selected location to show local flood risk.',cta:'Choose location'},{title:'See what the forecast means for your street.',copy:'Compare projected water levels with clear, human-readable depth guidance.',cta:'Continue'},{title:'Know where to go before conditions worsen.',copy:'StormSight compares your route to nearby shelters with projected flooding.',cta:'Enter StormSight'}];
function onboarding(){let s=steps[state.onboard];return `<main class="onboarding"><section class="onboard-scene"><img class="scene-map" src="hydro-map.png" alt="Local flood model">${state.onboard===1?'<div class="water-meter"><b>Projected depth</b><div class="water-levels"><i style="height:25%"></i><i style="height:50%"></i><i style="height:75%"></i><i style="height:100%"></i></div><small>0.5m · 1.0m · 1.5m · 2.0m</small></div>':''}${state.onboard===2?'<i class="route-line"></i>':''}</section><section class="onboard-content"><div class="step-indicator">${steps.map((_,i)=>`<i class="step-dot ${i===state.onboard?'active':''}"></i>`).join('')}</div><div class="eyebrow">GETTING STARTED · ${state.onboard+1} OF 3</div><h1>${s.title}</h1><p>${s.copy}</p><div class="onboard-actions">${state.onboard?'<button class="btn btn-outline" onclick="state.onboard--;render()">Back</button>':''}<button class="btn btn-primary" onclick="nextOnboard()">${s.cta}</button></div></section></main>`}
function locationPage(){return `<main class="location-page"><div class="location-top">${logo()}<button class="btn btn-outline nav-to" data-view="landing">Exit setup</button></div><h1>Where should StormSight monitor?</h1><p class="location-lead">Choose a location to see its local flood outlook and evacuation options.</p><div class="location-grid"><aside class="location-controls"><input class="search-input" aria-label="Search location" value="Tumana, Marikina" placeholder="Search barangay, city, or street"><button class="btn btn-quiet" onclick="toast('Using your approximate current location')">⌖ Use current location</button><div class="suggestions"><b>Suggested barangays</b>${['Tumana, Marikina','Nangka, Marikina','Malanday, Marikina','Santolan, Pasig'].map(x=>`<div class="suggestion"><span>${x}</span><button onclick="toast('${x} selected')">Select</button></div>`).join('')}</div><button class="btn btn-primary nav-to" data-view="overview" style="width:100%;margin-top:28px">Use this location</button></aside><div class="location-map" aria-label="Location map"><i class="pin" aria-hidden="true"></i></div></div></main>`}
function shell(view,body){return `<div class="app-shell"><aside class="sidebar ${state.sidebar?'open':''}">${logo()}<nav class="side-nav" aria-label="Application navigation">${nav.map(([v,l])=>`<button class="side-link nav-to ${view===v?'active':''}" data-view="${v}"><b>${icons[v]}</b><span>${l}</span></button>`).join('')}</nav><div class="side-bottom"><div class="monitor">MONITORING<strong>Tumana, Marikina</strong></div><button class="side-link nav-to ${view==='settings'?'active':''}" data-view="settings"><b>⚙</b><span>Settings</span></button><button class="side-link" onclick="toast('Offline data synced 12 minutes ago')"><b>↓</b><span>Offline Data</span></button></div></aside><section class="content"><header class="app-header"><div style="display:flex;align-items:center;gap:14px"><button class="menu-btn" onclick="state.sidebar=!state.sidebar;render()" aria-label="Toggle menu">☰</button><h1>${title(view)}<span class="demo-label">DEMO DATA</span></h1></div><span class="status-badge">Monitoring</span></header>${body}</section></div>`}
function title(v){return ({overview:'Tumana, Marikina',simulation:'Flood Simulation',forecast:'Forecast',evacuation:'Evacuation',alerts:'Alerts',saved:'Saved Locations',learn:'Learn',settings:'Settings'})[v]}
function overview(){return shell('overview',`<main class="overview"><div class="overview-intro"><div><div class="eyebrow">CURRENT FLOOD OUTLOOK</div><h2>Moderate flood risk</h2><div class="risk-copy"><b>Caution:</b> Water may reach knee to waist height in low-lying streets.</div></div><button class="btn btn-primary nav-to" data-view="simulation">Open simulation</button></div><div class="map-stage"><div class="map-top"><span>YOUR HOME</span><b>Tumana</b><span>Projected depth 0.8 m</span></div><div class="map-controls"><button class="map-control" aria-label="Zoom in">+</button><button class="map-control" aria-label="Zoom out">−</button><button class="map-control" aria-label="Recenter">⌖</button></div><i class="pin"></i></div><div class="info-rail">${[['Projected Depth','0.8 m'],['Expected Rainfall','180 mm'],['Storm Arrival','~36 hrs'],['Nearest Shelter','1.1 km']].map(x=>`<div class="info-cell"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div></main>`)}
function simulation(){return shell('simulation',`<main class="simulation"><div class="rain-overlay" id="rain"></div><section class="float-panel sim-status"><div class="eyebrow">SIMULATION</div><b>Tumana, Marikina</b><div class="big-depth" id="depth">${simDepth()} m</div><small>Projected water depth</small><div class="sim-stat"><span>Expected rainfall</span><b id="rainfall">${state.scenario==='likely'?220:310} mm</b></div><div class="sim-stat"><span>Scenario</span><b id="scenarioName">${state.scenario==='likely'?'Likely':'Worst case'}</b></div></section><div class="depth-legend">WATER DEPTH<div class="gradient"></div>0m · 0.5m · 1m · 1.5m · 2m · 3m+</div><section class="float-panel layers"><h3>Layers</h3>${['Flood water','Rainfall','Buildings','Roads','Rivers','Barangay boundaries','Evacuation centers'].map((x,i)=>`<label class="layer-row"><input type="checkbox" ${i<5?'checked':''} onchange="toggleLayer('${x}',this.checked)">${x}</label>`).join('')}</section><section class="float-panel timeline"><div class="timeline-row"><button class="play" onclick="togglePlay()" aria-label="${state.playing?'Pause':'Play'} simulation">${state.playing?'Ⅱ':'▶'}</button><input class="range" aria-label="Simulation timeline" type="range" min="0" max="100" value="${state.time}" oninput="state.time=+this.value;updateDepth()"><div class="scenario"><button class="${state.scenario==='likely'?'active':''}" onclick="setScenario('likely')">Likely</button><button class="${state.scenario==='worst'?'active':''}" onclick="setScenario('worst')">Worst Case</button></div></div><div class="time-labels"><span>−72h</span><span>NOW</span><span>LANDFALL</span></div></section></main>`)}
function simDepth(){return ((state.time/100)*(state.scenario==='likely'?1.8:2.7)).toFixed(1)}
function forecast(){return shell('forecast',`<main class="editorial"><div class="eyebrow">LOCAL WEATHER OUTLOOK</div><h2>Typhoon Kristine</h2><p class="risk-copy">Sample forecast scenario · updated for prototype</p><div class="editorial-grid"><div class="track-map" aria-label="Typhoon track mock visualization"><i class="philippines"></i><i class="storm-track"><i class="storm-dot"></i></i></div><aside class="data-panel"><h3>Approaching Luzon</h3>${[['Landfall','~36 hours'],['Wind','120 km/h'],['Rainfall','180–250 mm'],['Movement','West Northwest'],['Local match','25-year rainfall scenario']].map(x=>`<div class="data-row"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<button class="btn btn-primary nav-to" data-view="simulation">View Flood Simulation</button></aside></div></main>`)}
function evacuation(){return shell('evacuation',`<main class="evac-grid"><div class="evac-map"><i class="route green"></i><i class="route blue"></i><i class="route red"></i><i class="pin"></i></div><aside class="route-panel"><div class="eyebrow">ROUTE OPTIONS</div><div class="route-options"><button class="active" onclick="selectRoute(this,'Recommended Route','Low','Passable')">● Recommended</button><button onclick="selectRoute(this,'Alternative Route','Moderate','Use caution')">● Alternative</button><button onclick="selectRoute(this,'Flooded Route','High','Blocked')">× Unsafe / flooded</button></div><h2 id="routeTitle">Recommended Route</h2><p>Tumana Elementary School</p><div class="route-metric"><small>Distance · estimated time</small><b>1.1 km · 12 min</b></div><div class="route-metric"><small>Projected flood exposure</small><b id="exposure">Low</b></div><div class="route-metric"><small>Route status</small><b id="routeStatus">Passable</b></div><button class="btn btn-primary" style="width:100%;margin-top:25px" onclick="toast('Route opened in preview mode')">Open Route</button></aside></main>`)}
const alerts=[{t:'Heavy Rainfall Warning',m:'180–250 mm rainfall expected within the next 24 hours.',s:'Marikina · 18 minutes ago',items:['rapid rise in river level','flooding in low-lying streets','difficult travel']},{t:'Rising River Levels',m:'Marikina River is forecast to rise through the evening.',s:'Tumana · 42 minutes ago',items:['monitor riverside roads','move valuables higher','prepare to evacuate']},{t:'Typhoon Update',m:'Kristine continues west northwest toward Luzon.',s:'Metro Manila · 1 hour ago',items:['strong winds possible','heavy rain bands','conditions may change quickly']},{t:'Evacuation Advisory',m:'Pre-emptive evacuation may begin in priority zones.',s:'District 1 · 2 hours ago',items:['bring essential medicine','use recommended routes','check on neighbors']}];
function alertsPage(){let a=alerts[state.alert];return shell('alerts',`<main class="alerts-grid"><aside class="alert-list"><h2>Local alerts</h2>${alerts.map((x,i)=>`<button class="alert-row ${state.alert===i?'active':''}" onclick="state.alert=${i};render()"><strong><i class="severity"></i>${x.t}</strong><small>${x.s}</small></button>`).join('')}</aside><article class="alert-detail"><div class="eyebrow">WEATHER ADVISORY</div><h2>${a.t}</h2><p class="alert-meta">${a.s}</p><p class="impact">${a.m}</p><h3>Possible impacts</h3><ul>${a.items.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn btn-primary nav-to" data-view="simulation">Open Simulation</button></article></main>`)}
function learn(){return shell('learn',`<main class="learn"><section class="learn-hero"><div><div class="eyebrow">UNDERSTAND YOUR RISK</div><h2>What does 0.8 metres of water really mean?</h2><p class="hero-copy">Flood depth numbers become useful when you can picture their impact on people, homes, and roads.</p></div><div class="depth-diagram"><div style="height:25%"><span>0.5 m · knee</span></div><div style="height:50%"><span>1.0 m · waist</span></div><div style="height:75%"><span>1.5 m · chest</span></div><div style="height:100%"><span>2.0 m · dangerous</span></div></div></section>${[['Why Marikina floods','The Marikina River, low-lying neighborhoods, dense development, and intense rainfall can combine to raise water quickly.'],['Before a typhoon','Charge devices, download offline data, prepare medicine and documents, and agree on a family route.'],['Safe return after flooding','Wait for local clearance, avoid moving water, photograph damage safely, and treat floodwater as contaminated.']].map(x=>`<article class="article-row"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</main>`)}
function settings(){return shell('settings',`<main class="settings"><div class="eyebrow">PREFERENCES</div><h2>Settings</h2>${settingGroup('Saved Locations',[['Home — Tumana','Primary monitoring location'],['School','Tumana Elementary School'],['Add location','']])}${settingGroup('Notifications',[['Storm alerts','Important storm movement'],['Flood warnings','Projected local flooding'],['Evacuation alerts','Official guidance']],true)}${settingGroup('Language',[['Language','English · Filipino, Bisaya, Bikolano available']])}${settingGroup('Offline Data',[['Last sync','12 minutes ago'],['Storage size','84 MB'],['Sync now','Keep local maps available']])}${settingGroup('Accessibility',[['High contrast','Increase visual separation'],['Large text','Use larger interface text'],['Reduced motion','Limit weather animation']],true)}</main>`)}
function settingGroup(title,rows,toggles=false){return `<section class="settings-group"><h3>${title}</h3>${rows.map((x,i)=>`<div class="setting-row"><span><b>${x[0]}</b><small>${x[1]}</small></span>${toggles?`<button class="toggle ${i<2?'on':''}" aria-label="Toggle ${x[0]}" onclick="this.classList.toggle('on')"></button>`:'<button class="btn-quiet" onclick="toast(\''+x[0]+' selected\')">Edit</button>'}</div>`).join('')}</section>`}
function saved(){return shell('saved',`<main class="settings"><div class="eyebrow">MONITORED PLACES</div><h2>Saved Locations</h2>${[['Home','Tumana, Marikina · Moderate risk'],['School','Tumana Elementary School · Low risk']].map(x=>`<div class="setting-row"><span><b>${x[0]}</b><small>${x[1]}</small></span><button class="btn btn-outline nav-to" data-view="overview">View</button></div>`).join('')}<button class="btn btn-primary nav-to" data-view="location" style="margin-top:28px">Add location</button></main>`)}
function go(v){state.view=v;state.sidebar=false;history.replaceState(null,'','#'+v);render();scrollTo(0,0)}
function nextOnboard(){if(state.onboard<2){state.onboard++;render()}else go('location')}
function tiltHero(e){let s=document.querySelector('#assetStage');if(!s)return;let r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;s.style.transform=`rotateX(${-y*7}deg) rotateY(${x*9}deg) translateY(-4px)`}
function resetHero(){let s=document.querySelector('#assetStage');if(s)s.style.transform='rotateX(0) rotateY(0) translateY(0)'}
function setScenario(x){state.scenario=x;render()}
function togglePlay(){state.playing=!state.playing;render();if(state.playing)tick()}
function tick(){if(!state.playing)return;state.time=(state.time+1)%101;updateDepth();setTimeout(tick,120)}
function updateDepth(){let d=document.querySelector('#depth');if(d)d.textContent=simDepth()+' m';let r=document.querySelector('.range');if(r)r.value=state.time}
function toggleLayer(name,on){if(name==='Rainfall')document.querySelector('#rain')?.classList.toggle('hidden',!on);toast(`${name} ${on?'shown':'hidden'}`)}
function selectRoute(el,title,exposure,status){document.querySelectorAll('.route-options button').forEach(x=>x.classList.remove('active'));el.classList.add('active');document.querySelector('#routeTitle').textContent=title;document.querySelector('#exposure').textContent=exposure;document.querySelector('#routeStatus').textContent=status}
function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
function render(){let routes={landing,login:()=>auth('login'),signup:()=>auth('signup'),onboarding,location:locationPage,overview,simulation,forecast,evacuation,alerts:alertsPage,learn,settings,saved};app.innerHTML=(routes[state.view]||landing)();if(window.SSLanding){(routes[state.view]||landing)===landing?SSLanding.mount():SSLanding.unmount()}document.querySelectorAll('.nav-to').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));document.querySelectorAll('.scroll').forEach(b=>b.addEventListener('click',()=>document.querySelector('#'+b.dataset.target)?.scrollIntoView()))}
let initial=location.hash.slice(1);if(initial)state.view=initial;render();
